// Run trusted GNU find inventories across canonical system roots. Large roots are
// split at bounded-depth subtrees so a broad directory cannot monopolize a worker.
import { isUtf8 } from "node:buffer";
import { spawn } from "node:child_process";
import path from "node:path";

const FIND = "/usr/bin/find";
const MAX_OUTPUT = 64 * 1024 * 1024;
const MAX_ENUMERATION_OUTPUT = 64 * 1024 * 1024;
// This is a hard fail-closed bound. Keep the full inventory within it by letting GNU
// find optimize the cheap name predicates ahead of filesystem metadata checks.
const TIMEOUT_MS = 25_000;
const MAX_ENTRIES = 500_000;
const MAX_JOBS = 100_000;
const MAX_ROOTS = 4_096;
const MAX_ROOT_BYTES = 1024 * 1024;
// Amortize GNU find startup cost across disjoint system roots without approaching
// the per-process argv size limit on Linux.
const MAX_ENUMERATION_ROOTS = 64;
const MAX_ENUMERATION_ROOT_BYTES = 64 * 1024;
// Bundle enough sibling directories to avoid spawning one `find` process for
// every pair on large hosted system roots, while keeping independent jobs for
// bounded parallel scanning.
const DIRECTORY_BATCH_SIZE = 64;
const DIRECT_ENTRY_BATCH_SIZE = 256;
const SCAN_WORKERS = 8;
const COMPILER_NAMES = [
  "go", "go[0-9]*", "go-[0-9]*",
  "rustc", "rustc[0-9]*", "rustc-[0-9]*",
  "cargo", "cargo[0-9]*", "cargo-[0-9]*",
  "rustup",
];

function findArgs(roots) {
  const nameExpression = COMPILER_NAMES.flatMap((name, index) => index === 0
    ? ["-name", name]
    : ["-o", "-name", name]);
  const linkTargetExpression = COMPILER_NAMES.flatMap((name, index) => {
    const patterns = [name, `*/${name}`];
    return patterns.flatMap((pattern, patternIndex) => index === 0 && patternIndex === 0
      ? ["-lname", pattern]
      : ["-o", "-lname", pattern]);
  });
  return [
    "-O3", "-P", ...roots,
    "(", "(", "-type", "l", "(", ...nameExpression, "-o", ...linkTargetExpression, ")", ")",
    "-o",
    "(", "(", ...nameExpression, ")", "-a", "-type", "f", "-a", "-perm", "/111", ")",
    ")", "-print0",
  ];
}

const roots = process.argv.slice(2);
const rootBytes = roots.reduce((total, root) => total + Buffer.byteLength(root) + 1, 0);
if (roots.length === 0 || roots.length > MAX_ROOTS || rootBytes > MAX_ROOT_BYTES || roots.some((root) => !root.startsWith("/"))) {
  process.stderr.write("compiler inventory roots must be absolute and within bounded input limits\n");
  process.exit(2);
}

async function* enumerateJobs() {
  let entryCount = 0;
  let jobCount = 0;
  let enumerationBytes = 0;
  let rootOffset = 0;
  let batchIndex = 0;
  while (rootOffset < roots.length) {
    const batch = [];
    let batchBytes = 0;
    while (rootOffset < roots.length && batch.length < MAX_ENUMERATION_ROOTS) {
      const root = roots[rootOffset];
      const rootBytes = Buffer.byteLength(root) + 1;
      if (batch.length > 0 && batchBytes + rootBytes > MAX_ENUMERATION_ROOT_BYTES) break;
      batch.push(root);
      batchBytes += rootBytes;
      rootOffset += 1;
    }
    const child = spawn(FIND, ["-P", ...batch, "-mindepth", "1", "-maxdepth", "3", "-printf", "%d\\0%y\\0%p\\0"], {
      env: { HOME: "/nonexistent", LANG: "C", PATH: "/usr/bin:/bin" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    children.add(child);
    let stderrBytes = 0;
    let spawnError = null;
    child.stderr.on("data", (chunk) => {
      stderrBytes += chunk.length;
      failed = true;
      stopAll("enumeration_stderr");
    });
    child.on("error", (error) => {
      spawnError = error;
      failed = true;
      stopAll("enumeration_spawn_error");
    });
    const closed = new Promise((resolve) => child.once("close", (code, signal) => resolve({ code, signal })));
    let scanDirectories = [];
    let directEntries = [];
    let entryDepth = null;
    let entryType = null;
    let pending = Buffer.alloc(0);
    try {
      for await (const chunk of child.stdout) {
        enumerationBytes += chunk.length;
        if (enumerationBytes > MAX_ENUMERATION_OUTPUT) {
