  failureReason ??= reason;
  if (stopping) return;
  stopping = true;
  for (const child of children) child.kill("SIGTERM");
  void jobs.return().catch(() => {});
  killTimer = setTimeout(() => {
    for (const child of children) child.kill("SIGKILL");
  }, 1_000);
  killTimer.unref();
}

process.on("SIGTERM", () => {
  failed = true;
  stopAll("terminated");
});
process.on("SIGINT", () => {
  failed = true;
  stopAll("interrupted");
});

const deadline = setTimeout(() => {
  failed = true;
  stopAll("deadline");
}, TIMEOUT_MS);

function scanRoots(roots) {
  return new Promise((resolve) => {
    const child = spawn(FIND, findArgs(roots), {
      env: { HOME: "/nonexistent", LANG: "C", PATH: "/usr/bin:/bin" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    children.add(child);
    const stdout = [];
    let stderrBytes = 0;
    child.stdout.on("data", (chunk) => {
      outputBytes += chunk.length;
      if (outputBytes > MAX_OUTPUT) {
        failed = true;
        stopAll("output_limit");
        return;
      }
      stdout.push(chunk);
    });
    child.stderr.on("data", (chunk) => {
      stderrBytes += chunk.length;
      failed = true;
      stopAll("find_stderr");
    });
    child.on("error", () => {
      failed = true;
      stopAll("spawn_error");
    });
    child.on("close", (code) => {
      children.delete(child);
      if (code !== 0 || stderrBytes !== 0) {
        failed = true;
        stopAll(stderrBytes ? "find_stderr" : "find_exit");
      }
      outputs.push(stdout);
      resolve();
    });
  });
}

async function worker() {
  while (!failed) {
    try {
      const next = await jobs.next();
      if (failed || next.done) return;
      await scanRoots(next.value);
    } catch {
      failed = true;
      stopAll();
      return;
    }
  }
}

