clearTimeout(deadline);
clearTimeout(killTimer);
if (failed) {
  process.stderr.write(`trusted compiler inventory could not complete: ${failureReason ?? "unknown"}\n`);
  process.exitCode = 1;
} else {
  const output = Buffer.concat(outputs.flat(), outputBytes);
  if (!isUtf8(output)) {
